def get_weather(city):
    return f"The weather in {city} is sunny, 24C"

def agent(task):
    t = task.lower()
    if "weather" in t or "temperature" in t:
        for word in ["in ", "for "]:
            if word in t:
                city = t.split(word)[-1].strip()
                result = get_weather(city)
                return {"task": task, "result": result}
        result = get_weather(task)
    else:
        result = "I can only check weather"
    return {"task": task, "result": result}
